import os
from datetime import datetime, timedelta, timezone

import jwt
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from jwt.exceptions import InvalidTokenError
from pwdlib import PasswordHash

SECRET_KEY = os.environ.get("SECRET_KEY")
if not SECRET_KEY:
    raise RuntimeError("Set SECRET_KEY in the environment")

DEMO_USERNAME = os.environ.get("DEMO_USERNAME", "ada")
DEMO_PASSWORD = os.environ["DEMO_PASSWORD"]
password_hash = PasswordHash.recommended()
users = {
    DEMO_USERNAME: {
        "username": DEMO_USERNAME,
        "hashed_password": password_hash.hash(DEMO_PASSWORD),
    }
}

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")


def create_access_token(username: str) -> str:
    expires_at = datetime.now(timezone.utc) + timedelta(minutes=30)
    return jwt.encode(
        {"sub": username, "exp": expires_at}, SECRET_KEY, algorithm="HS256"
    )


@app.post("/token")
async def login(form: OAuth2PasswordRequestForm = Depends()):
    user = users.get(form.username)
    if user is None or not password_hash.verify(
        form.password, user["hashed_password"]
    ):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return {
        "access_token": create_access_token(user["username"]),
        "token_type": "bearer",
    }


@app.get("/users/me")
async def read_users_me(token: str = Depends(oauth2_scheme)):
    try:
        claims = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])
    except InvalidTokenError as exc:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid or expired token",
            headers={"WWW-Authenticate": "Bearer"},
        ) from exc

    username = claims.get("sub")
    user = users.get(username) if isinstance(username, str) else None
    if user is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid or expired token",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return {"username": user["username"]}
